    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value == 1:
                path = [(r, c), (r, c + 1), (r, c + 2), (r - 1, c + 2)]
                for rr, cc in path[1:-1]:
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 5
                rr, cc = path[-1]
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 1
            elif value == 2:
                path = [(r, c - d) for d in range(5)]
                for rr, cc in path[1:-1]:
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 5
                rr, cc = path[-1]
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 2
            elif value == 3:
                path = [(r + d, c) for d in range(4)]
                for rr, cc in path[1:-1]:
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 5
                rr, cc = path[-1]
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 3
            elif value == 6:
                path = [(r - d, c) for d in range(7)]
                for rr, cc in path[1:-1]:
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 5
                rr, cc = path[-1]
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 6
            else:
                continue
            paths.append(set(path))

    intersections = set()
    for i, first in enumerate(paths):
        for second in paths[i + 1:]:
            intersections.update(first & second)

    for r, c in intersections:
        rr, cc = r, c
        while rr < h and cc >= 0:
            out[rr][cc] = 4
            rr += 1
            cc -= 1

    return out
